-- Catalog of common plants (mostly houseplants). The plant form suggests names from it while the
-- user types and fills in the scientific name, type, light and watering interval.
-- Anyone signed in can read it; to add or fix entries, edit the table in the Supabase dashboard.
CREATE TABLE IF NOT EXISTS public.plant_catalog (
  id serial PRIMARY KEY,
  name_fa text NOT NULL UNIQUE,
  aliases text[] NOT NULL DEFAULT '{}',
  latin_name text NOT NULL,
  type text NOT NULL DEFAULT 'indoor' CHECK (type IN ('indoor', 'garden', 'cactus', 'aquatic')),
  light_level text CHECK (light_level IN ('low', 'medium', 'high')),
  watering_interval_days integer CHECK (watering_interval_days BETWEEN 1 AND 60)
);

ALTER TABLE public.plant_catalog ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "catalog readable by signed-in users" ON public.plant_catalog;
CREATE POLICY "catalog readable by signed-in users" ON public.plant_catalog
  FOR SELECT TO authenticated USING (true);
GRANT SELECT ON public.plant_catalog TO authenticated;

ON CONFLICT (name_fa) DO NOTHING;
